package io.github.diodeme.ji.session.memory;

import io.github.diodeme.ji.ai.Message;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.session.SessionSnapshot;
import io.github.diodeme.ji.session.SessionStore;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** In-process canonical SessionStore with atomic per-Session CAS updates. */
public final class MemorySessionStore implements SessionStore {
    private final Map<String, SessionSnapshot> sessions = new LinkedHashMap<>();

    @Override
    public synchronized SessionSnapshot create(String sessionId, ModelRef model, String workingDirectory) {
        if (sessions.containsKey(sessionId)) throw new IllegalStateException("session already exists: " + sessionId);
        var snapshot = new SessionSnapshot(sessionId, 0, model, workingDirectory, List.of(), Usage.ZERO, Optional.empty());
        sessions.put(sessionId, snapshot);
        return snapshot;
    }

    @Override
    public synchronized Optional<SessionSnapshot> load(String sessionId) {
        return Optional.ofNullable(sessions.get(sessionId));
    }

    @Override
    public synchronized SessionSnapshot startRun(String sessionId, String runId, Message userMessage, long expectedRevision) {
        SessionSnapshot current = require(sessionId, expectedRevision);
        if (current.activeRun().isPresent()) throw new IllegalStateException("session already has an active run");
        var transcript = new java.util.ArrayList<>(current.transcript());
        transcript.add(userMessage);
        var next = new SessionSnapshot(sessionId, increment(current.revision()), current.model(), current.workingDirectory(),
                transcript, current.usage(), Optional.of(new SessionSnapshot.ActiveRun(runId, SessionSnapshot.Status.RUNNING, 0)));
        sessions.put(sessionId, next);
        return next;
    }

    @Override
    public synchronized SessionSnapshot append(String sessionId, String runId, List<Message> messages, Usage usage,
                                                Optional<SessionSnapshot.ActiveRun> activeRun, long expectedRevision) {
        SessionSnapshot current = require(sessionId, expectedRevision);
        SessionSnapshot.ActiveRun prior = current.activeRun().orElseThrow(() -> new IllegalStateException("session has no active run"));
        if (!prior.runId().equals(runId)) throw new IllegalStateException("run does not own session");
        activeRun.ifPresent(next -> {
            if (!next.runId().equals(runId) || next.revision() != prior.revision() + 1) {
                throw new IllegalStateException("active run transition is stale or belongs to another run");
            }
        });
        var transcript = new java.util.ArrayList<>(current.transcript());
        transcript.addAll(messages);
        var next = new SessionSnapshot(sessionId, increment(current.revision()), current.model(), current.workingDirectory(),
                transcript, current.usage().plus(usage), activeRun);
        sessions.put(sessionId, next);
        return next;
    }

    private SessionSnapshot require(String sessionId, long expectedRevision) {
        SessionSnapshot current = sessions.get(sessionId);
        if (current == null) throw new IllegalStateException("session not found: " + sessionId);
        if (current.revision() != expectedRevision) {
            throw new IllegalStateException("session revision conflict: expected " + expectedRevision + ", current " + current.revision());
        }
        return current;
    }

    private static long increment(long value) {
        return Math.incrementExact(value);
    }
}
